-- 데이터베이스 세트 369. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_sql_index_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 369, 'SQL 인덱스 손연습: CREATE INDEX·SHOW INDEX, EXPLAIN 읽기, UNIQUE·복합 인덱스, DROP INDEX', '회원 1,000명이 든 members 테이블에서 인덱스를 직접 만들고 지워 봅니다. 인덱스를 만들고 목록을 보고, EXPLAIN 으로 쿼리가 인덱스를 쓰는지 인덱스 전후를 비교하고, 중복을 막는 UNIQUE 인덱스와 두 컬럼을 묶은 인덱스를 만들고, LIKE 패턴에 따라 인덱스를 쓰는지 달라지는 것을 확인합니다. 채점은 인덱스 상태와 EXPLAIN 출력 파일을 직접 비교합니다.', 'linux-db', '데이터베이스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 369);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 1, '인덱스 만들기', '**배경** — 인덱스는 책의 찾아보기처럼, 컬럼 값으로 행을 빨리 찾게 해 주는 별도의 자료 구조입니다. 이 세트의 모든 문제는 회원 1,000명이 든 `members` 테이블(`mariadb shop` 으로 접속)을 씁니다.

- 컬럼: `id`(기본 키, 1~1000), `name`(`user<id>`), `email`(`user<id>@example.com`), `city`(Seoul·Busan·Daegu·Incheon 이 번갈아), `age`(20~59)
- 처음부터 `age` 에는 `idx_age` 인덱스가 걸려 있습니다. 문제마다 처음 상태에서 다시 시작합니다.

**문제** — `city` 컬럼에 **`idx_city`** 라는 이름의 인덱스를 만드세요.', '`CREATE INDEX 인덱스이름 ON 테이블 (컬럼);` 형태입니다.', 'mariadb shop -e ''CREATE INDEX idx_city ON members (city);''
mariadb shop -e ''SHOW INDEX FROM members;''

# CREATE INDEX 이름 ON 테이블 (컬럼) 으로 만들고 SHOW INDEX 로 확인한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(60) NOT NULL, city VARCHAR(20) NOT NULL, age INT NOT NULL);\\nINSERT INTO members SELECT seq, CONCAT(\\"user\\",seq), CONCAT(\\"user\\",seq,\\"@example.com\\"), ELT(seq%4+1,\\"Seoul\\",\\"Busan\\",\\"Daegu\\",\\"Incheon\\"), 20+seq%40 FROM seq_1_to_1000;\\nCREATE INDEX idx_age ON members (age);\\nANALYZE TABLE members;'' >/dev/null; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_city''\\")\\" = \\"city\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_age''\\")\\" = \\"age\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "idx_city 가 city 컬럼에 만들어졌다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_city''\\")\\" = \\"city\\" ]"]}, {"label": "기존 idx_age 는 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_age''\\")\\" = \\"age\\" ]"]}]', '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 2, '만들어진 인덱스 목록 보기', '`members` 테이블에 걸린 인덱스 목록을 조회해 출력을 **`/tmp/q2.txt`** 에 저장하세요.', '`SHOW INDEX FROM 테이블;` 은 인덱스 이름, 컬럼, 고유 여부 등을 보여 줍니다.', 'mariadb shop -e ''SHOW INDEX FROM members;'' > /tmp/q2.txt
cat /tmp/q2.txt

# SHOW INDEX FROM 테이블 로 인덱스 목록을 본다. PRIMARY 키도 인덱스로 나온다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(60) NOT NULL, city VARCHAR(20) NOT NULL, age INT NOT NULL);\\nINSERT INTO members SELECT seq, CONCAT(\\"user\\",seq), CONCAT(\\"user\\",seq,\\"@example.com\\"), ELT(seq%4+1,\\"Seoul\\",\\"Busan\\",\\"Daegu\\",\\"Incheon\\"), 20+seq%40 FROM seq_1_to_1000;\\nCREATE INDEX idx_age ON members (age);\\nANALYZE TABLE members;'' >/dev/null; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(cat /tmp/q2.txt)\\" = \\"$(mariadb shop -e ''SHOW INDEX FROM members'')\\" ] ) && ( grep -q PRIMARY /tmp/q2.txt && grep -q idx_age /tmp/q2.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q2.txt 가 지금의 SHOW INDEX 출력과 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q2.txt)\\" = \\"$(mariadb shop -e ''SHOW INDEX FROM members'')\\" ]"]}, {"label": "PRIMARY 와 idx_age 가 보인다", "cmd": ["sh", "-c", "grep -q PRIMARY /tmp/q2.txt && grep -q idx_age /tmp/q2.txt"]}]', '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 3, '쿼리가 인덱스를 쓰는지 EXPLAIN 으로 보기', '**배경** — 쿼리 앞에 `EXPLAIN` 을 붙이면 쿼리를 실행하지 않고 DB 가 세운 **실행 계획** 을 표로 보여 줍니다. 이 세트에서 읽을 컬럼은 다음과 같습니다.

- `type`: 행을 찾는 방식. `ALL` 은 테이블 전체 훑기(느림), `ref`·`range` 는 인덱스로 찾기
- `key`: 실제로 쓴 인덱스 이름 (`NULL` 이면 인덱스를 쓰지 않음)
- `rows`: 읽을 것으로 예상하는 행 수
- `Extra`: 추가 정보

**문제** — `age` 가 30 인 회원을 조회하는 `SELECT * FROM members WHERE age = 30` 이 **어떤 인덱스를 쓰는지** `EXPLAIN` 으로 확인하고, 그 출력을 **`/tmp/q3.txt`** 에 저장하세요.', '쿼리 앞에 `EXPLAIN` 을 붙이면 실제로 실행하지 않고 실행 계획을 보여 줍니다. 결과의 `key` 컬럼이 실제로 쓴 인덱스입니다.', 'mariadb shop -e ''EXPLAIN SELECT * FROM members WHERE age = 30;'' > /tmp/q3.txt
cat /tmp/q3.txt

# EXPLAIN 결과의 key 컬럼에 idx_age 가 보이면 그 인덱스를 쓴 것이다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(60) NOT NULL, city VARCHAR(20) NOT NULL, age INT NOT NULL);\\nINSERT INTO members SELECT seq, CONCAT(\\"user\\",seq), CONCAT(\\"user\\",seq,\\"@example.com\\"), ELT(seq%4+1,\\"Seoul\\",\\"Busan\\",\\"Daegu\\",\\"Incheon\\"), 20+seq%40 FROM seq_1_to_1000;\\nCREATE INDEX idx_age ON members (age);\\nANALYZE TABLE members;'' >/dev/null; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(tail -n1 /tmp/q3.txt | cut -f6)\\" = \\"idx_age\\" ] ) && ( grep -qw members /tmp/q3.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "key 컬럼이 idx_age 이다", "cmd": ["sh", "-c", "[ \\"$(tail -n1 /tmp/q3.txt | cut -f6)\\" = \\"idx_age\\" ]"]}, {"label": "members 테이블의 계획이다", "cmd": ["sh", "-c", "grep -qw members /tmp/q3.txt"]}]', '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 4, '인덱스 전과 후 비교하기', '`email` 이 `user500@example.com` 인 회원을 찾는 `SELECT * FROM members WHERE email = ''user500@example.com''` 로 다음을 하세요. ① 인덱스를 만들기 **전** 의 `EXPLAIN` 출력을 **`/tmp/before.txt`**, ② `email` 컬럼에 **`idx_email`** 인덱스를 만든 뒤의 `EXPLAIN` 출력을 **`/tmp/after.txt`** 에 저장.', '`EXPLAIN` 결과의 `type` 컬럼이 `ALL` 이면 테이블 전체를 훑는다는 뜻이고, `key` 가 `NULL` 이면 인덱스를 쓰지 않았다는 뜻입니다.', 'mariadb shop -e "EXPLAIN SELECT * FROM members WHERE email = ''user500@example.com'';" > /tmp/before.txt
mariadb shop -e ''CREATE INDEX idx_email ON members (email);''
mariadb shop -e "EXPLAIN SELECT * FROM members WHERE email = ''user500@example.com'';" > /tmp/after.txt
cat /tmp/before.txt /tmp/after.txt

# 같은 쿼리의 EXPLAIN 을 인덱스 전후로 비교한다. 전에는 type ALL, 후에는 key 에 인덱스가 나온다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(60) NOT NULL, city VARCHAR(20) NOT NULL, age INT NOT NULL);\\nINSERT INTO members SELECT seq, CONCAT(\\"user\\",seq), CONCAT(\\"user\\",seq,\\"@example.com\\"), ELT(seq%4+1,\\"Seoul\\",\\"Busan\\",\\"Daegu\\",\\"Incheon\\"), 20+seq%40 FROM seq_1_to_1000;\\nCREATE INDEX idx_age ON members (age);\\nANALYZE TABLE members;'' >/dev/null; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(tail -n1 /tmp/before.txt | cut -f4)\\" = \\"ALL\\" ] ) && ( [ \\"$(tail -n1 /tmp/before.txt | cut -f6)\\" = \\"NULL\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_email''\\")\\" = \\"email\\" ] ) && ( [ \\"$(tail -n1 /tmp/after.txt | cut -f6)\\" = \\"idx_email\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "전: type 이 ALL 이다", "cmd": ["sh", "-c", "[ \\"$(tail -n1 /tmp/before.txt | cut -f4)\\" = \\"ALL\\" ]"]}, {"label": "전: key 가 NULL 이다", "cmd": ["sh", "-c", "[ \\"$(tail -n1 /tmp/before.txt | cut -f6)\\" = \\"NULL\\" ]"]}, {"label": "idx_email 이 email 컬럼에 만들어졌다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_email''\\")\\" = \\"email\\" ]"]}, {"label": "후: key 가 idx_email 이다", "cmd": ["sh", "-c", "[ \\"$(tail -n1 /tmp/after.txt | cut -f6)\\" = \\"idx_email\\" ]"]}]', '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 5, '중복을 막는 인덱스 (UNIQUE)', '`email` 컬럼에 **같은 값이 두 번 들어갈 수 없게** 하는 인덱스 **`uq_email`** 을 만드세요. 그런 다음 이미 있는 이메일(`user1@example.com`)로 새 회원 (id 1001, name `dup`, city `Seoul`, age 25)을 넣어 보고, **나온 오류 메시지** 를 **`/tmp/q5.txt`** 에 저장하세요(`2>`).', '`CREATE UNIQUE INDEX ...` 입니다. 중복 값을 넣으면 `Duplicate entry` 오류가 나며, 오류는 표준 에러 출력이라 `2> 파일` 로 저장합니다.', 'mariadb shop -e ''CREATE UNIQUE INDEX uq_email ON members (email);''
mariadb shop -e "INSERT INTO members VALUES (1001, ''dup'', ''user1@example.com'', ''Seoul'', 25);" 2> /tmp/q5.txt
cat /tmp/q5.txt

# UNIQUE 인덱스는 같은 값의 삽입을 거부한다. 오류는 stderr 라 2> 로 저장한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(60) NOT NULL, city VARCHAR(20) NOT NULL, age INT NOT NULL);\\nINSERT INTO members SELECT seq, CONCAT(\\"user\\",seq), CONCAT(\\"user\\",seq,\\"@example.com\\"), ELT(seq%4+1,\\"Seoul\\",\\"Busan\\",\\"Daegu\\",\\"Incheon\\"), 20+seq%40 FROM seq_1_to_1000;\\nCREATE INDEX idx_age ON members (age);\\nANALYZE TABLE members;'' >/dev/null; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''uq_email''\\")\\" = \\"email\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT non_unique FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''uq_email''\\")\\" = \\"0\\" ] ) && ( grep -q \\"Duplicate entry\\" /tmp/q5.txt ) && ( [ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM members\\")\\" = \\"1000\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "uq_email 이 email 에 만들어졌다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''uq_email''\\")\\" = \\"email\\" ]"]}, {"label": "uq_email 은 고유 인덱스다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT non_unique FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''uq_email''\\")\\" = \\"0\\" ]"]}, {"label": "q5.txt 에 Duplicate entry 오류가 있다", "cmd": ["sh", "-c", "grep -q \\"Duplicate entry\\" /tmp/q5.txt"]}, {"label": "중복 행은 들어가지 않았다 (1000명)", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM members\\")\\" = \\"1000\\" ]"]}]', '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 6, '두 컬럼을 묶은 인덱스', '`city` 와 `age` 를 **이 순서로** 묶은 인덱스 **`idx_city_age`** 를 만드세요.', '`CREATE INDEX 이름 ON 테이블 (컬럼1, 컬럼2);` 처럼 괄호 안에 컬럼을 쉼표로 나열합니다. 순서가 중요합니다.', 'mariadb shop -e ''CREATE INDEX idx_city_age ON members (city, age);''
mariadb shop -e ''SHOW INDEX FROM members;''

# 여러 컬럼을 괄호 안에 순서대로 나열하면 복합 인덱스가 된다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(60) NOT NULL, city VARCHAR(20) NOT NULL, age INT NOT NULL);\\nINSERT INTO members SELECT seq, CONCAT(\\"user\\",seq), CONCAT(\\"user\\",seq,\\"@example.com\\"), ELT(seq%4+1,\\"Seoul\\",\\"Busan\\",\\"Daegu\\",\\"Incheon\\"), 20+seq%40 FROM seq_1_to_1000;\\nCREATE INDEX idx_age ON members (age);\\nANALYZE TABLE members;'' >/dev/null; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_city_age''\\")\\" = \\"city,age\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "idx_city_age 의 컬럼이 city, age 순서다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_city_age''\\")\\" = \\"city,age\\" ]"]}]', '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 7, 'LIKE 앞부분 고정과 와일드카드 비교', '`email` 에 `idx_email` 인덱스를 만든 뒤, 두 쿼리의 `EXPLAIN` 을 각각 저장하세요. ① `WHERE email LIKE ''user77%''` → **`/tmp/q7a.txt`**, ② `WHERE email LIKE ''%77@example.com''` → **`/tmp/q7b.txt`**. 두 결과가 어떻게 다른지 `key` 컬럼을 보세요.', '`LIKE` 패턴이 문자로 시작하면 인덱스에서 그 값부터 찾아 갈 수 있지만, 맨 앞이 `%` 이면 어디서 시작할지 알 수 없습니다.', 'mariadb shop -e ''CREATE INDEX idx_email ON members (email);''
mariadb shop -e "EXPLAIN SELECT * FROM members WHERE email LIKE ''user77%'';" > /tmp/q7a.txt
mariadb shop -e "EXPLAIN SELECT * FROM members WHERE email LIKE ''%77@example.com'';" > /tmp/q7b.txt
cat /tmp/q7a.txt /tmp/q7b.txt

# 앞부분이 정해진 LIKE 는 인덱스를 쓰고, 맨 앞이 % 인 LIKE 는 인덱스를 쓰지 못한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(60) NOT NULL, city VARCHAR(20) NOT NULL, age INT NOT NULL);\\nINSERT INTO members SELECT seq, CONCAT(\\"user\\",seq), CONCAT(\\"user\\",seq,\\"@example.com\\"), ELT(seq%4+1,\\"Seoul\\",\\"Busan\\",\\"Daegu\\",\\"Incheon\\"), 20+seq%40 FROM seq_1_to_1000;\\nCREATE INDEX idx_age ON members (age);\\nANALYZE TABLE members;'' >/dev/null; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_email''\\")\\" = \\"email\\" ] ) && ( [ \\"$(tail -n1 /tmp/q7a.txt | cut -f6)\\" = \\"idx_email\\" ] ) && ( [ \\"$(tail -n1 /tmp/q7b.txt | cut -f6)\\" = \\"NULL\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "idx_email 이 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_email''\\")\\" = \\"email\\" ]"]}, {"label": "① key 가 idx_email 이다", "cmd": ["sh", "-c", "[ \\"$(tail -n1 /tmp/q7a.txt | cut -f6)\\" = \\"idx_email\\" ]"]}, {"label": "② key 가 NULL 이다", "cmd": ["sh", "-c", "[ \\"$(tail -n1 /tmp/q7b.txt | cut -f6)\\" = \\"NULL\\" ]"]}]', '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 8, '인덱스 지우기', '`members` 에서 `idx_age` 인덱스를 **삭제** 하세요. 테이블의 데이터와 기본 키는 그대로여야 합니다.', '`DROP INDEX 인덱스이름 ON 테이블;` 입니다. 인덱스를 지워도 행은 지워지지 않습니다.', 'mariadb shop -e ''DROP INDEX idx_age ON members;''
mariadb shop -e ''SHOW INDEX FROM members;''

# DROP INDEX 이름 ON 테이블 로 인덱스만 지운다. 데이터는 그대로다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(60) NOT NULL, city VARCHAR(20) NOT NULL, age INT NOT NULL);\\nINSERT INTO members SELECT seq, CONCAT(\\"user\\",seq), CONCAT(\\"user\\",seq,\\"@example.com\\"), ELT(seq%4+1,\\"Seoul\\",\\"Busan\\",\\"Daegu\\",\\"Incheon\\"), 20+seq%40 FROM seq_1_to_1000;\\nCREATE INDEX idx_age ON members (age);\\nANALYZE TABLE members;'' >/dev/null; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_age''\\")\\" = \\"0\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''PRIMARY''\\")\\" = \\"id\\" ] ) && ( [ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM members\\")\\" = \\"1000\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "idx_age 가 없다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''idx_age''\\")\\" = \\"0\\" ]"]}, {"label": "PRIMARY 는 남아 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index) FROM information_schema.statistics WHERE table_schema = ''shop'' AND table_name = ''members'' AND index_name = ''PRIMARY''\\")\\" = \\"id\\" ]"]}, {"label": "회원은 1000명 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb shop -N -e \\"SELECT COUNT(*) FROM members\\")\\" = \\"1000\\" ]"]}]', '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 9, 'EXPLAIN 의 Extra 읽기', '`idx_age` 인덱스에 들어 있는 `age` 컬럼**만** 조회하는 쿼리 하나(`age = 30` 조건)를 `EXPLAIN` 해서 **`/tmp/q9.txt`** 에 저장하고, 마지막 컬럼 `Extra` 에 인덱스만으로 답했다는 표시(`Using index`)가 나오게 하세요.', '`SELECT *` 대신 필요한 컬럼만 고르면, 인덱스 안의 값만으로 답할 수 있어 테이블 행을 읽지 않아도 됩니다.', 'mariadb shop -e ''EXPLAIN SELECT age FROM members WHERE age = 30;'' > /tmp/q9.txt
cat /tmp/q9.txt

# 인덱스에 있는 컬럼만 조회하면 Extra 에 Using index 가 나온다(테이블 행을 읽지 않는다)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE members (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(60) NOT NULL, city VARCHAR(20) NOT NULL, age INT NOT NULL);\\nINSERT INTO members SELECT seq, CONCAT(\\"user\\",seq), CONCAT(\\"user\\",seq,\\"@example.com\\"), ELT(seq%4+1,\\"Seoul\\",\\"Busan\\",\\"Daegu\\",\\"Incheon\\"), 20+seq%40 FROM seq_1_to_1000;\\nCREATE INDEX idx_age ON members (age);\\nANALYZE TABLE members;'' >/dev/null; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(tail -n1 /tmp/q9.txt | cut -f6)\\" = \\"idx_age\\" ] ) && ( tail -n1 /tmp/q9.txt | cut -f10 | grep -q \\"Using index\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "key 가 idx_age 이다", "cmd": ["sh", "-c", "[ \\"$(tail -n1 /tmp/q9.txt | cut -f6)\\" = \\"idx_age\\" ]"]}, {"label": "Extra 에 Using index 가 있다", "cmd": ["sh", "-c", "tail -n1 /tmp/q9.txt | cut -f10 | grep -q \\"Using index\\""]}]', '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 10, '인덱스를 너무 많이 만들면?', '조회를 빠르게 하려고 컬럼마다 인덱스를 잔뜩 만들면 생기는 **대표적인 부담** 은 무엇일까요?', '조회가 아니라 데이터를 바꾸는 쪽을 생각해 보세요.', NULL, NULL, '[]', 'choice', '["모든 조회가 항상 인덱스 때문에 더 느려진다", "행을 넣거나 고칠 때 인덱스도 함께 갱신해야 해서 쓰기가 느려지고 저장 공간도 더 쓴다", "같은 값을 가진 행은 하나도 저장할 수 없게 된다", "테이블의 행이 인덱스 컬럼 순서로 영구히 다시 쓰여 원본 순서를 잃는다"]', 1, '인덱스는 별도의 자료 구조라서 `INSERT`·`UPDATE`·`DELETE` 때 함께 갱신해야 하고 저장 공간도 차지합니다. 그래서 자주 조회하는 조건에 맞춰 필요한 만큼만 만듭니다. 조회가 항상 느려지는 것은 아니고, 중복을 막는 것은 `UNIQUE` 인덱스일 때뿐입니다.', NULL, NULL, NULL, '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 11, '중복을 막는 인덱스 만들기', '`email` 값이 겹치지 않게 **같은 값을 두 번 넣을 수 없는** 인덱스를 만드는 문장입니다. 빈칸을 채우세요.', '값이 하나뿐이어야 한다는 뜻의 단어예요.', NULL, NULL, '[]', 'fill', '["UNIQUE", "DISTINCT", "SINGLE", "ONLY"]', NULL, '`CREATE UNIQUE INDEX` 는 같은 값이 두 번 들어가지 못하게 하는 고유 인덱스를 만듭니다. `DISTINCT` 는 조회 결과의 중복을 없앨 때 쓰고, `SINGLE`·`ONLY` 는 이 자리에 쓰는 키워드가 아닙니다.', '[0]', 'CREATE {0} INDEX uq_email ON members (email);', NULL, '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 369, 12, '느린 조회를 인덱스로 개선하는 흐름', '느린 조회를 인덱스로 개선하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '계획 확인 → 인덱스 → 다시 확인 순서예요.', NULL, NULL, '[]', 'order', '["`EXPLAIN` 으로 현재 실행 계획을 본다 (`type` 이 `ALL` 인지)", "조건에 쓰는 컬럼에 `CREATE INDEX` 로 인덱스를 만든다", "같은 쿼리를 `EXPLAIN` 으로 다시 본다 (`key` 에 인덱스가 나오는지)", "필요 없는 인덱스는 `DROP INDEX` 로 정리한다"]', NULL, '먼저 `EXPLAIN` 으로 지금 계획을 확인하고, 조건에 쓰는 컬럼에 인덱스를 만든 뒤, 같은 쿼리의 `EXPLAIN` 을 다시 비교합니다. 쓰이지 않는 인덱스는 쓰기 부담만 늘리므로 정리합니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "MariaDB CREATE INDEX", "url": "https://mariadb.com/kb/en/create-index/"}, {"title": "MariaDB DROP INDEX", "url": "https://mariadb.com/kb/en/drop-index/"}, {"title": "MariaDB SHOW INDEX", "url": "https://mariadb.com/kb/en/show-index/"}, {"title": "MariaDB EXPLAIN", "url": "https://mariadb.com/kb/en/explain/"}, {"title": "MariaDB 인덱스 시작하기", "url": "https://mariadb.com/kb/en/getting-started-with-indexes/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 369 AND order_index = 12);

